index 0000000..3f8944b
--- /dev/null
+++ b/src/explore/pilot/rig.ts
@@ -0,0 +1,129 @@
+/* ===== Người treo dù: một bộ nhân vật + trang bị gắn dưới một cánh (src/explore/pilot/rig.ts) =====
+   Cây nút (hệ group dù: +X bay, +Y lên, +Z phải):
+     ex-pilot (Group, lớp 1)
+     ├─ wing  (Object3D tĩnh tại gốc group dù: đầu trên của dây treo / dây phanh)
+     ├─ swing (Group tại điểm tụ dây = đỉnh riser, (0, exHangY + riser, 0); lắc con lắc swingRoll / Pitch / Yaw; cũng là xương `hang` của trang bị)
+     │  └─ bản sao nhân vật (gốc tại hông: (−hang.fore, −riser − hang.up, 0) so với swing), AnimationMixer phát `sit`
+     └─ gear (SkinnedMesh trang bị, hình học dùng chung mọi dù, Skeleton riêng)
+   Người treo quay quanh điểm tụ dây (cả riser, carabiner, người đi cùng nhau), dây treo trên đó đứng yên trong hệ dù.
+   Quai phanh treo theo riser nên tính trong hệ lắc: điểm nắm = hông + (toggle.fore + hang.fore, toggle.up + hang.up − phanh·travel, ±toggle.half).
+   Trang bị: Skeleton [wing, hang, Pelvis, Spine2, L Hand, R Hand, L Thigh, R Thigh, pack]; boneInverses = nghịch đảo ma trận từng xương trong hệ ex-pilot
+   đo ở tư thế bay nền (pose 0, phanh nền, sau mixer.update(0)), bindMatrix đơn vị ⇒ dù ở đâu trong thế giới cũng đúng. Không cấp phát mỗi khung. */
+import * as THREE from 'three';
+import { CONFIG } from '../../config';
+import { exHangY } from '../glider';
+import { PlReact, type PlSignals } from './react';
+import { PlBones } from './bones';
+import { plGearGeometry, plGearMaterial, type PlGearRest } from './gear';
+import type { PlSource } from './load';
+
+const _tL = new THREE.Vector3(), _tR = new THREE.Vector3();
+
+/* Hình học trang bị dùng chung theo nguồn (vị trí nghỉ giống nhau mọi dù: cùng mô hình, cùng tư thế nền) */
+const gearGeo = new WeakMap<PlSource, THREE.BufferGeometry>();
+
+export class PlRig {
+  readonly group = new THREE.Group();
+  readonly wing = new THREE.Object3D();
+  readonly swing = new THREE.Group();
+  readonly root: THREE.Object3D;
+  readonly mixer: THREE.AnimationMixer;
+  readonly react: PlReact;
+  readonly bones: PlBones;
+  readonly gear: THREE.SkinnedMesh;
+  readonly pack = new THREE.Object3D();
+  readonly rest: PlGearRest;
+
+  constructor(src: PlSource, seed: number) {
+    const P = CONFIG.explore.pilot;
+    this.group.name = 'ex-pilot';
+    this.wing.name = 'pl-wing'; this.swing.name = 'pl-swing'; this.pack.name = 'pl-pack';
+    this.group.add(this.wing, this.swing);
+    this.swing.position.set(0, exHangY + P.riser, 0);
+    this.root = src.clone(src.scene);
+    this.root.name = 'pl-body';
+    this.root.position.set(-P.hang.fore, -P.riser - P.hang.up, 0);
+    this.swing.add(this.root);
+    this.mixer = new THREE.AnimationMixer(this.root);
+    this.mixer.clipAction(src.clip).play();
+    this.react = new PlReact(seed);
+    this.bones = new PlBones(this.root);
+    this.bones.spines[2].add(this.pack);
+    this.bones.pack = this.pack;
+    /* tư thế bay nền: số đo ở `sit`, rồi áp pose 0 (phanh nền) */
+    this.mixer.update(0);
+    this.bones.capture();
+    this.bones.measure();
+    this.pose(0);
+    /* đo vị trí nghỉ + nghịch đảo xương trong hệ ex-pilot */
+    this.group.updateMatrixWorld(true);
+    const inv = this.group.matrixWorld.clone().invert();
+    const b = this.bones, bl = [this.wing, this.swing, b.pelvis, b.spines[2], b.arms[0].hand, b.arms[1].hand, b.thigh[0], b.thigh[1], this.pack];
+    const rel = bl.map((o) => inv.clone().multiply(o.matrixWorld));
+    const pos = (m: THREE.Matrix4) => { const v = new THREE.Vector3().setFromMatrixPosition(m); return [v.x, v.y, v.z]; };
+    const toG = (v: THREE.Vector3) => { const w = v.clone().applyMatrix4(this.root.matrixWorld).applyMatrix4(inv); return [w.x, w.y, w.z]; };
+    const dirG = (v: THREE.Vector3) => { const w = v.clone().transformDirection(this.root.matrixWorld).transformDirection(inv); return [w.x, w.y, w.z]; };
+    const grip = (i: number) => toG(b.arms[i].target);
+    const bar = (i: number) => { const a = b.arms[i]; return dirG(a.fH.clone().applyQuaternion(a.D).cross(a.nH.clone().applyQuaternion(a.D)).normalize()); };
+    const up = (i: number) => { const a = b.arms[i]; return dirG(a.fH.clone().applyQuaternion(a.D)); };
+    b.updateMatrices();
+    this.rest = {
+      hang: [0, exHangY, 0], pelvis: pos(rel[2]), spine: pos(rel[3]), handL: pos(rel[4]), handR: pos(rel[5]), thighL: pos(rel[6]), thighR: pos(rel[7]),
+      kneeL: toG(b.pC(b.calf[0], new THREE.Vector3())), kneeR: toG(b.pC(b.calf[1], new THREE.Vector3())),
+      gripL: grip(0), gripR: grip(1), barL: bar(0), barR: bar(1), fingL: up(0), fingR: up(1)
+    };
+    let geo = gearGeo.get(src);
+    if (!geo) gearGeo.set(src, geo = plGearGeometry(this.rest));
+    const sk = new THREE.Skeleton(bl as THREE.Bone[], rel.map((m) => m.invert()));
+    this.gear = new THREE.SkinnedMesh(geo, plGearMaterial());
+    this.gear.name = 'pl-gear';
+    this.gear.bind(sk, new THREE.Matrix4());
+    this.gear.frustumCulled = false; this.gear.castShadow = false; this.gear.receiveShadow = false;
+    this.group.add(this.gear);
+    this.group.traverse((o) => o.layers.set(1));
+  }
+
+  /* Áp pose hiện tại của react lên lắc + xương (sau mixer) */
+  private pose(dt: number): void {
+    const P = CONFIG.explore.pilot, p = this.react.pose, T = P.toggle, H = P.hang;
+    this.bones.restore();
+    this.mixer.update(dt);
+    this.bones.capture();
+    this.swing.rotation.set(p.swingRoll, p.swingYaw, p.swingPitch, 'YZX');
+    const x = T.fore + H.fore, y0 = T.up + H.up;
+    _tL.set(x, y0 - p.brakeL * T.travel, -T.half);
+    _tR.set(x, y0 - p.brakeR * T.travel, T.half);
+    this.bones.apply(p, _tL, _tR);
+  }
+
+  /* Mỗi khung: tín hiệu → lò xo → xương. dt không hợp lệ / ≤ 0 → không tiến thời gian (vẫn áp tư thế) */
+  update(sig: PlSignals, dt: number): void {
+    const d = dt > 0 && Number.isFinite(dt) ? Math.min(dt, CONFIG.explore.pilot.dtMax) : 0;
+    this.react.step(sig, d);
+    this.pose(d);
+  }
+
+  /* Nhảy vị trí / đổi chủ: lò xo về nghỉ */
+  reset(): void { this.react.reset(); }
+
+  /* m — sai số điểm nắm ↔ quai phanh hai tay */
+  handErr(): [number, number] { return [this.bones.handErr(0), this.bones.handErr(1)]; }
+
+  /* Tâm thân trong hệ thế giới (cho test chụp ảnh / camera) */
+  chest(out: THREE.Vector3): THREE.Vector3 {
+    this.group.updateMatrixWorld(true);
+    return out.setFromMatrixPosition(this.bones.spines[2].matrixWorld);
+  }
+
+  /* Gỡ khỏi dù, bỏ mixer, giải phóng skeleton riêng (bản sao nhân vật + trang bị). Hình học / texture / vật liệu của nguồn và hình học trang bị dùng chung giữ lại */
+  dispose(): void {
+    this.mixer.stopAllAction();
+    this.mixer.uncacheRoot(this.root);
+    this.group.removeFromParent();
+    const seen = new Set<THREE.Skeleton>();
+    this.group.traverse((o) => {
+      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
+      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
+    });
+  }
+}
diff --git a/tests/pilot-shots.mjs b/tests/pilot-shots.mjs
new file mode 100644
index 0000000..297830e
--- /dev/null
+++ b/tests/pilot-shots.mjs
@@ -0,0 +1,113 @@
+// Ảnh chụp người treo dù có xương (D-035 Task 4) để xem bằng mắt — KHÔNG phải test chấm điểm.
+//   npm run build && node tests/pilot-shots.mjs [--only=straight,left] [--set='{"base":{"recline":0.3}}'] [--measure] [--w=1280 --h=720]
+// Mở dist/ với ?test, ghi đè CONFIG.explore.pilot (--set, trộn sâu) rồi cất cánh, chờ nhân vật thật gắn xong, đóng băng vòng bay (explore.update rỗng)
+// và tự bước mô phỏng bằng explore.step. Mỗi trạng thái (thẳng; giữ rẽ trái 3 s; rẽ phải; E 2 s; Q 2 s) chụp vài góc quanh người treo trong hệ dù:
+// sau 4 m, ngang trái 3 m, trước 3,5 m, camera bám mặc định, cận tay trái 1,2 m; thêm đêm và mưa bão cho góc sau.
+// Ảnh: tests/screens/pilot-<trạng thái>-<góc>.png. In pilotDebug() mỗi trạng thái. --measure: in mặt cắt thân người (hệ dù) để chỉnh trang bị.
+import { fileURLToPath } from 'node:url';
+import { mkdirSync, writeFileSync } from 'node:fs';
+import { serveDir, launch, openApp, frames } from './lib.mjs';
+import { setWx } from './weather-lib.mjs';
+
+const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
+const only = arg('only', '') ? arg('only', '').split(',') : null;
+const W = Number(arg('w', 1280)), H = Number(arg('h', 720));
+const set = { loadMs: 180000, ...JSON.parse(arg('set', '{}')) };   // SwiftShader: khung đầu chặn luồng chính hàng chục giây, nới giờ tải
+const OUT = fileURLToPath(new URL('./screens/', import.meta.url));
+mkdirSync(OUT, { recursive: true });
+
+const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
+const browser = await launch();
+const t0 = Date.now();
+const log = (...a) => console.log(`[${((Date.now() - t0) / 1000).toFixed(0)} s]`, ...a);
+try {
+  const { page, errors } = await openApp(browser, srv.url, { width: W, height: H });
+  log('trang đã mở');
+  await page.evaluate((set) => {
+    const merge = (a, b) => { for (const k of Object.keys(b)) { if (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) merge(a[k], b[k]); else a[k] = b[k]; } };
+    merge(window.__app.exFlight.CONFIG_explore.pilot, set);
+    window.__app.explore.start();
+    window.__app.explore.update = () => {};   // đóng băng: chỉ explore.step trong script tiến mô phỏng
+  }, set);
+  await page.waitForFunction(() => { window.__app.explore.step(1 / 60, { turn: 0, climb: 0, throttle: 0 }); const d = window.__app.explore.pilotDebug(); return d && d.real; }, null, { timeout: 240000, polling: 1000 });
+  log('nhân vật thật đã gắn');
+
+  /* Bước mô phỏng sec giây với đầu vào inp (dt 1/60) */
+  const run = (inp, sec) => page.evaluate(([inp, sec]) => { for (let i = 0; i < Math.round(sec * 60); i++) window.__app.explore.step(1 / 60, inp); }, [inp, sec]);
+  /* Đặt camera: off = [x, y, z] m trong hệ dù so với ngực (null = camera bám mặc định), nhìn vào ngực (hoặc bàn tay trái khi hand) */
+  const shot = async (name, off, hand = false) => {
+    await page.evaluate(([off, hand]) => {
+      const { explore, camera, THREE } = window.__app;
+      if (!off) { camera.near = 0.5; camera.updateProjectionMatrix(); window.__app.exFlight.exChase(camera, window.__app.controls.target, explore.state, 0, true); return; }   // camera bám mặc định, đặt thẳng
+      const g = explore.glider; g.updateMatrixWorld(true);
+      const body = g.getObjectByName('pl-body');
+      const tgt = new THREE.Vector3().setFromMatrixPosition((hand ? body.getObjectByName('Bip01_L_Hand') : body.getObjectByName('Bip01_Spine2')).matrixWorld);
+      const loc = g.worldToLocal(tgt.clone()).add(new THREE.Vector3(...off));
+      camera.position.copy(g.localToWorld(loc)); camera.up.set(0, 1, 0); camera.lookAt(tgt);
+      camera.near = 0.05; camera.updateProjectionMatrix();
+    }, [off, hand]);
+    await frames(page, 2);
+    await page.screenshot({ path: `${OUT}pilot-${name}.png` });
+    log('ảnh', name);
+  };
+  const dbg = async (label) => {
+    const d = await page.evaluate(() => { const d = window.__app.explore.pilotDebug(); const p = {}; for (const k in d.pose) p[k] = +d.pose[k].toFixed(3); return { real: d.real, handErr: d.handErr.map((v) => +v.toFixed(4)), calls: d.calls, pose: p }; });
+    log(`pilotDebug ${label}:`, JSON.stringify(d));
+    return d;
+  };
+  const restart = () => page.evaluate(() => { const ex = window.__app.explore, upd = ex.update; ex.start(); ex.update = upd; });
+
+  const ANG = { back: [-4, 0.3, 0], left: [0, 0.2, -3], front: [3.5, 0.2, 0], right: [0, 0.2, 3], chase: null, hand: [0.7, 0.3, -0.9], top: [-1.5, 2.2, 1.2] };
+  const states = [
+    ['straight', { turn: 0, climb: 0, throttle: 0 }, 2.5, ['back', 'left', 'front', 'chase', 'hand', 'top']],
+    ['turnL', { turn: 1, climb: 0, throttle: 0 }, 3, ['back', 'front', 'chase', 'hand']],
+    ['turnR', { turn: -1, climb: 0, throttle: 0 }, 3, ['back', 'front']],
+    ['fast', { turn: 0, climb: 0, throttle: 1 }, 2, ['left']],
+    ['slow', { turn: 0, climb: 0, throttle: -1 }, 2, ['left']]
+  ];
+  const report = {};
+  for (const [name, inp, sec, angs] of states) {
+    if (only && !only.includes(name)) continue;
+    await restart(); await run({ turn: 0, climb: 0, throttle: 0 }, 2); await run(inp, sec);
+    report[name] = await dbg(name);
+    for (const a of angs) {
+      await page.evaluate((inp) => window.__app.explore.step(1 / 60, inp), inp);
+      await shot(`${name}-${a}`, ANG[a], a === 'hand');
+    }
+  }
+  if (process.argv.includes('--measure')) {
+    await restart(); await run({ turn: 0, climb: 0, throttle: 0 }, 2);
+    const m = await page.evaluate(() => {
+      const { explore, THREE } = window.__app, g = explore.glider; g.updateMatrixWorld(true);
+      const pil = g.getObjectByName('ex-pilot'), body = g.getObjectByName('pl-body');
+      let mesh = null; body.traverse((o) => { if (o.isSkinnedMesh) mesh = o; });
+      mesh.skeleton.update();
+      const inv = pil.matrixWorld.clone().invert(), v = new THREE.Vector3(), pts = [];
+      for (let i = 0; i < mesh.geometry.attributes.position.count; i += 1) { mesh.getVertexPosition(i, v); v.applyMatrix4(mesh.matrixWorld).applyMatrix4(inv); pts.push([+v.x.toFixed(3), +v.y.toFixed(3), +v.z.toFixed(3)]); }
+      const bones = {};
+      for (const n of ['Pelvis', 'Spine', 'Spine2', 'Neck', 'Head', 'L_Clavicle', 'L_UpperArm', 'L_Forearm', 'L_Hand', 'L_Thigh', 'L_Calf', 'L_Foot', 'R_Thigh', 'R_Hand']) {
+        const b = body.getObjectByName('Bip01_' + n); v.setFromMatrixPosition(b.matrixWorld).applyMatrix4(inv); bones[n] = [+v.x.toFixed(3), +v.y.toFixed(3), +v.z.toFixed(3)];
+      }
+      return { bones, pts };
+    });
+    writeFileSync(`${OUT}pilot-measure.json`, JSON.stringify(m));
+    log('bones', JSON.stringify(m.bones));
+  }
+  if (!only || only.includes('night')) {
+    await restart(); await run({ turn: 0, climb: 0, throttle: 0 }, 2.5);
+    await page.evaluate(() => { window.__app.dayNight.target = 1; window.__app.dayNight.night = 1; });
+    await frames(page, 3);
+    await shot('night-back', ANG.back); await shot('night-chase', null);
+    await page.evaluate(() => { window.__app.dayNight.target = 0; window.__app.dayNight.night = 0; });
+    await setWx(page, 'storm');
+    await run({ turn: 0, climb: 0, throttle: 0 }, 1);
+    report.storm = await dbg('storm');
+    await shot('storm-back', ANG.back); await shot('storm-chase', null);
+    await setWx(page, 'now');
+  }
+  writeFileSync(`${OUT}pilot-report.json`, JSON.stringify(report, null, 1));
+  if (errors.length) log('lỗi console:', errors.slice(0, 5));
+} finally {
+  await browser.close(); srv.close();
+}
+log('xong');
